CREATE TABLE tenant (tenant_id varchar(128) PRIMARY KEY, epoch bigint NOT NULL DEFAULT 1 CHECK(epoch>0));
CREATE TABLE membership (tenant_id varchar(128) NOT NULL REFERENCES tenant, issuer text NOT NULL, subject_id varchar(128) NOT NULL, roles text[] NOT NULL, department varchar(256), clearance bigint, suspended boolean, administrative boolean NOT NULL DEFAULT false, active boolean NOT NULL DEFAULT true, PRIMARY KEY(tenant_id,issuer,subject_id));
CREATE TABLE resource (tenant_id varchar(128) NOT NULL REFERENCES tenant, resource_id varchar(128) NOT NULL, resource_type varchar(128) NOT NULL, department varchar(256), classification bigint, resource_version bigint NOT NULL CHECK(resource_version>0), PRIMARY KEY(tenant_id,resource_id));
CREATE TABLE policy_version (tenant_id varchar(128) NOT NULL REFERENCES tenant, version bigint NOT NULL, content text NOT NULL CHECK(octet_length(content)<=262144), digest char(64) NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY(tenant_id,version));
CREATE TABLE role (tenant_id varchar(128) NOT NULL, version bigint NOT NULL, role_name varchar(128) NOT NULL, PRIMARY KEY(tenant_id,version,role_name), FOREIGN KEY(tenant_id,version) REFERENCES policy_version);
CREATE TABLE role_edge (tenant_id varchar(128) NOT NULL, version bigint NOT NULL, child varchar(128) NOT NULL, parent varchar(128) NOT NULL, PRIMARY KEY(tenant_id,version,child,parent), FOREIGN KEY(tenant_id,version,child) REFERENCES role(tenant_id,version,role_name), FOREIGN KEY(tenant_id,version,parent) REFERENCES role(tenant_id,version,role_name));
CREATE TABLE "grant" (tenant_id varchar(128) NOT NULL, version bigint NOT NULL, role_name varchar(128) NOT NULL, action varchar(128) NOT NULL, resource_type varchar(128) NOT NULL, PRIMARY KEY(tenant_id,version,role_name,action,resource_type), FOREIGN KEY(tenant_id,version,role_name) REFERENCES role(tenant_id,version,role_name));
CREATE TABLE active_policy (tenant_id varchar(128) PRIMARY KEY REFERENCES tenant, version bigint NOT NULL, FOREIGN KEY(tenant_id,version) REFERENCES policy_version);
CREATE TABLE audit (tenant_id varchar(128) NOT NULL REFERENCES tenant, audit_id uuid NOT NULL, principal_ref varchar(128) NOT NULL, action varchar(128) NOT NULL, resource_ref varchar(128) NOT NULL, epoch bigint NOT NULL, result varchar(32) NOT NULL, reason varchar(64) NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY(tenant_id,audit_id));
CREATE INDEX audit_tenant_time ON audit(tenant_id,created_at DESC);
CREATE FUNCTION immutable_policy() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN RAISE EXCEPTION 'immutable policy revision'; END $$;
CREATE TRIGGER immutable_version BEFORE UPDATE OR DELETE ON policy_version FOR EACH ROW EXECUTE FUNCTION immutable_policy();
CREATE ROLE gatehouse_runtime LOGIN PASSWORD 'local-gatehouse-only' NOSUPERUSER NOCREATEDB NOCREATEROLE NOBYPASSRLS;
GRANT USAGE ON SCHEMA public TO gatehouse_runtime;
GRANT SELECT,UPDATE ON tenant TO gatehouse_runtime;
GRANT SELECT,INSERT,UPDATE ON membership,active_policy TO gatehouse_runtime;
GRANT SELECT ON resource TO gatehouse_runtime;
GRANT SELECT,INSERT ON audit TO gatehouse_runtime;
GRANT SELECT,INSERT ON policy_version,role,role_edge,"grant" TO gatehouse_runtime;
DO $$ DECLARE tab text; BEGIN FOREACH tab IN ARRAY ARRAY['tenant','membership','resource','policy_version','role','role_edge','grant','active_policy','audit'] LOOP EXECUTE format('ALTER TABLE %I ENABLE ROW LEVEL SECURITY',tab); EXECUTE format('ALTER TABLE %I FORCE ROW LEVEL SECURITY',tab); EXECUTE format('CREATE POLICY tenant_boundary ON %I USING (tenant_id = current_setting(''gatehouse.tenant'',true)) WITH CHECK (tenant_id = current_setting(''gatehouse.tenant'',true))',tab); END LOOP; END $$;
-- Defense in depth: security-relevant state changes bump the epoch even outside HTTP adapters.
CREATE FUNCTION advance_authorization_epoch() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN UPDATE tenant SET epoch=epoch+1 WHERE tenant_id=COALESCE(NEW.tenant_id,OLD.tenant_id); RETURN COALESCE(NEW,OLD); END $$;
CREATE TRIGGER membership_epoch AFTER INSERT OR UPDATE OR DELETE ON membership FOR EACH ROW EXECUTE FUNCTION advance_authorization_epoch();
CREATE TRIGGER resource_epoch AFTER INSERT OR UPDATE OR DELETE ON resource FOR EACH ROW EXECUTE FUNCTION advance_authorization_epoch();
CREATE TRIGGER publication_epoch AFTER INSERT OR UPDATE OR DELETE ON active_policy FOR EACH ROW EXECUTE FUNCTION advance_authorization_epoch();

CREATE FUNCTION resource_revision() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN IF NEW.tenant_id<>OLD.tenant_id OR NEW.resource_id<>OLD.resource_id THEN RAISE EXCEPTION 'resource key is immutable'; END IF; NEW.resource_version=OLD.resource_version+1; RETURN NEW; END $$;
CREATE TRIGGER resource_revision BEFORE UPDATE ON resource FOR EACH ROW EXECUTE FUNCTION resource_revision();
CREATE FUNCTION monotonic_publication() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN IF NEW.tenant_id<>OLD.tenant_id OR NEW.version<=OLD.version THEN RAISE EXCEPTION 'active policy must increase monotonically'; END IF; RETURN NEW; END $$;
CREATE TRIGGER monotonic_publication BEFORE UPDATE ON active_policy FOR EACH ROW EXECUTE FUNCTION monotonic_publication();
